import React, { useState, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Helmet } from 'react-helmet-async';
import { Card, Grid, Button, Typography, Divider, Box, InputLabel, Switch, } from '@mui/material';
import Iconify from '../../components/iconify';
import { useMyContext } from '../provider';
import useResponsive from '../../hooks/useResponsive';
import InputField from '../../components/input/inputField';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import { axios } from '../../utils/axios';

const AdminRolesForm = () => {
    const navigate = useNavigate();
    const { i18, fetchProfileData } = useMyContext();
    const location = useLocation();
    const queryParams = new URLSearchParams(location.search);
    const adminRolesIds = queryParams.get('adminRoleId') || null;
    const isMobile = useResponsive('down', 'sm');
    const [roleValue, setRoleValue] = useState('');
    const [descriptionValue, setDescriptionValue] = useState('');
    const [permissionArray, setPermissionArray] = useState([]);
    const [roleError, setRoleError] = useState('');
    const [descriptionError, setDescriptionError] = useState('');

    useEffect(() => {
        if (!adminRolesIds) {
            fetchMenulistArray();
        }
    }, []);

    const fetchMenulistArray = async () => {
        try {
            const response = await axios.get(`module/auth/admin/menusList`)
            if (response.status === 200) {
                const { menusList } = response?.data?.data
                // debugger
                setPermissionArray(menusList)
                console.log("setPermissionArray",menusList)
            }
        } catch (error) {
            console.error(error.message);
        }
    }

    useEffect(() => {
        if (adminRolesIds) {
            fetchAdminRoleData();
        }
    }, [adminRolesIds]);

    const fetchAdminRoleData = async () => {
        try {
            const response = await axios.get(`module/auth/adminRole/${adminRolesIds}`);
            if (response.status === 200) {
                const { role, description, permission } = response?.data?.data?.adminRole;
                setRoleValue(role);
                setDescriptionValue(description);
                // debugger
                setPermissionArray(permission);
            }
        } catch (error) {
            GenerateToastConfig(error.message);
        }
    };

    const backToRoute = () => {
        navigate('/dashboard/adminRoles')
    }

    const handleFieldChange = (event, status) => {
        const { value } = event.target;

        if (/^[A-Za-z\s]*$/.test(value)) {
            if (status === 'role') {
                setRoleValue(value);
                if (value.length < 2) {
                    setRoleError('Role is too short');
                } else {
                    setRoleError('');
                }
            } else if (status === 'description') {
                setDescriptionValue(value);
                if (value.length < 2) {
                    setDescriptionError('Description is too short');
                } else {
                    setDescriptionError('');
                }
            }
        }
    };

    // Toggle handler for main menu items
    // const handleMenuToggle = (index) => {
    //     const updatedPermissions = [...permissionArray];
    //     updatedPermissions[index].status = !updatedPermissions[index].status;
    //     setPermissionArray(updatedPermissions);
    // };

    const handleMenuToggle = (index) => {
        const updatedPermissions = [...permissionArray];
        const menu = updatedPermissions[index];
        
        // Toggle main menu and update submenus accordingly
        const newStatus = !menu.status;
        menu.status = newStatus;
        
        // Set all submenus to the same status as the main menu
        if (menu.subMenu && menu.subMenuList.length > 0) {
            menu.subMenuList = menu.subMenuList.map(subMenu => ({
                ...subMenu,
                status: newStatus
            }));
        }
    // debugger;
        setPermissionArray(updatedPermissions);
    };    

    // Toggle handler for subMenu items
    // const handleSubMenuToggle = (mainIndex, subIndex) => {
    //     const updatedPermissions = [...permissionArray];
    //     updatedPermissions[mainIndex].subMenuList[subIndex].status = !updatedPermissions[mainIndex].subMenuList[subIndex].status;
    //     setPermissionArray(updatedPermissions);
    // };

    const handleSubMenuToggle = (mainIndex, subIndex) => {
        const updatedPermissions = [...permissionArray];
        const mainMenu = updatedPermissions[mainIndex];
        const subMenu = mainMenu.subMenuList[subIndex];
        
        // Toggle the specific submenu
        subMenu.status = !subMenu.status;
        
        // Check if all submenus are true
        const allSubMenusTrue = mainMenu.subMenuList.every(subMenu => subMenu.status === true);
        
        // Set main menu status based on submenus
        mainMenu.status = allSubMenusTrue;
    // debugger;
        setPermissionArray(updatedPermissions);
    };    

    const addorupdateAdminRole = async () => {
        try {
            const payload = {
                role: roleValue,
                description: descriptionValue,
                permission: permissionArray,
            };
    
            let response;
            if (adminRolesIds) {
                response = await axios.put(`module/auth/adminRole/${adminRolesIds}`, payload);
            } else {
                response = await axios.post('module/auth/adminRole', payload);
            }
    
            if (response?.status === 200 || response?.status === 201) {
                GenerateToastConfig(response?.data?.message, "success");
    
                // Fetch updated profile data after submission
                // await fetchProfileData();
                // window.location.reload();
                fetchProfileData();
    
                // Navigate back to the admin roles page
                navigate('/dashboard/adminRoles');
            }
        } catch (error) {
            console.error(error.message);
            GenerateToastConfig(error.message);
        }
    };
    
    return (
        <>
            <Helmet>
                <title>{adminRolesIds ? 'Edit Admin Role' : 'Add Admin Role'}</title>
            </Helmet>

            <Card>
                <Grid container sx={{ padding: '10px 30px', margin: '10px 0px' }}>
                    <Grid container item justifyContent="space-between" alignItems="center" sx={{ marginRight: '10px' }}>
                        <Box sx={{ display: 'flex', alignItems: 'center' }}>
                            <Box
                                sx={{
                                    width: '37px',
                                    height: '37px',
                                    background: '#FF5A60',
                                    display: 'flex',
                                    alignItems: 'center',
                                    justifyContent: 'center',
                                    borderRadius: '50%',
                                    cursor: 'pointer',
                                }}
                                onClick={backToRoute}
                            >
                                <Iconify icon={'mdi:arrow-left'} width={24} height={24} color="white" />
                            </Box>
                            <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
                                {adminRolesIds ? i18?.ACCOUNTSTITLE?.EDIT_ADMINROLE || "Edit Admin Role" : i18?.ACCOUNTSTITLE?.ADD_ADMINROLE || "Add Admin Role"}
                            </Typography>
                        </Box>
                    </Grid>
                </Grid>

                <Divider sx={{ backgroundColor: '#333', margin: '10px 0px 10px 0px' }} />

                <Grid container={!isMobile} sx={{ padding: '10px 30px', margin: '10px 0px' }}>
                    <Grid item xs={6} sx={{ padding: !isMobile ? '10px 50px 10px 0px' : '0px 5px' }}>
                        <InputField
                            value={roleValue}
                            name="role"
                            label={i18?.ACCOUNTSTITLE?.ROLE || "Role"}
                            sx={{
                                margin: '10px 0px',
                                width: '100%',
                                '& .MuiInputBase-input.MuiOutlinedInput-input': {
                                    padding: '10.5px 14px',
                                },
                            }}
                            onChange={(e) => handleFieldChange(e, 'role')}
                            type="text"
                            required
                        />
                        {roleError && <Typography color="error">{roleError}</Typography>}
                    </Grid>
                    <Grid item xs={6} sx={{ padding: !isMobile ? '10px 50px 10px 0px' : '0px 5px' }}>
                        <InputField
                            value={descriptionValue}
                            name="description"
                            label={i18?.ACCOUNTSTITLE?.DESCRIPTION || "Description"}
                            sx={{
                                margin: '10px 0px',
                                width: '100%',
                                '& .MuiInputBase-input.MuiOutlinedInput-input': {
                                    padding: '10.5px 14px',
                                },
                            }}
                            onChange={(e) => handleFieldChange(e, 'description')}
                            type="text"
                            required
                        />
                        {descriptionError && <Typography color="error">{descriptionError}</Typography>}
                    </Grid>
                </Grid>

                <Grid sx={{ padding: '10px 30px', margin: '10px 0px' }}>
                    <InputLabel>{i18?.ACCOUNTSTITLE?.MENUPERMISSION || "Menu Permission"}</InputLabel>
                    {permissionArray.map((menu, index) => (
                        <Grid item xs={6} key={index}>
                            <Box
                                sx={{
                                    border: '1px solid #ccc',
                                    borderRadius: '4px',
                                    padding: '10px',
                                    margin: '10px 0',
                                    display: 'flex',
                                    justifyContent: 'space-between',
                                    alignItems: 'center',
                                }}
                            >
                                <Typography variant="body1">
                                    {i18?.ACCOUNTSTITLE?.[menu.menu] || menu.menu}
                                </Typography>
                                <Switch
                                    checked={menu.status}
                                    onChange={() => handleMenuToggle(index)}
                                    color="primary"
                                />
                            </Box>

                            {menu.subMenu && menu.subMenuList.length > 0 && (
                                <Box sx={{ paddingLeft: 4 }}>
                                    {menu.subMenuList.map((subMenu, subIndex) => (
                                        <Box
                                            key={subIndex}
                                            sx={{
                                                border: '1px solid #ccc',
                                                borderRadius: '4px',
                                                padding: '10px',
                                                marginTop: '10px',
                                                display: 'flex',
                                                justifyContent: 'space-between',
                                                alignItems: 'center',
                                            }}
                                        >
                                            <Typography variant="body2">
                                                {i18?.ACCOUNTSTITLE?.[subMenu.menu] || subMenu.menu}
                                            </Typography>
                                            <Switch
                                                checked={subMenu.status}
                                                onChange={() => handleSubMenuToggle(index, subIndex)}
                                                sx={{
                                                    color: 'lightpink',
                                                    '& .Mui-checked': {
                                                        color: 'lightpink',
                                                    },
                                                    '& .Mui-checked + .MuiSwitch-track': {
                                                        backgroundColor: 'lightpink',
                                                    },
                                                }}
                                            />
                                        </Box>
                                    ))}
                                </Box>
                            )}
                        </Grid>
                    ))}
                </Grid>


                <Divider sx={{ backgroundColor: '#333', margin: '10px 0px 10px 0px' }} />

                <Grid container justifyContent="flex-end" sx={{ padding: '10px 30px', margin: '10px 0px' }}>
                    <Button
                        sx={{
                            padding: '10px 58px'
                        }}
                        disabled={!roleValue || !descriptionValue}
                        variant="contained"
                        onClick={addorupdateAdminRole}
                    >
                        {adminRolesIds ? i18?.ACCOUNTSTITLE?.UPDATE || 'Update' : i18?.ACCOUNTSTITLE?.ADD || 'Add'}
                    </Button>
                </Grid>

            </Card>
        </>
    )
}

export default AdminRolesForm
